// Сутки — UTC, як на бекенді (domain/trade_day_stats.py): угода належить
// дню, коли її закрито, а день — [00:00:00.000, 24:00) UTC. Одні й ті самі
// межі для головної, історії трейдів і аналітики.
export const DAY_MS = 86400000;
// 00:00 UTC доби, в яку потрапляє ts.
export const utcDayStart = (ts) => ts - (((ts % DAY_MS) + DAY_MS) % DAY_MS);
// Перша й остання мілісекунда доби — обидві включно, як фільтри API.
export const utcDayRange = (ts) => {
    const start_ts = utcDayStart(ts);
    return { start_ts, end_ts: start_ts + DAY_MS - 1 };
};
// Доба на n днів раніше/пізніше. У UTC немає переходу на літній час, тож
// крок рівно в добу завжди потрапляє на сусідню календарну дату.
export const shiftUtcDay = (dayStart, n) => utcDayStart(dayStart) + n * DAY_MS;
export const todayUtc = () => utcDayStart(Date.now());
// «21.11.2026» — дата доби в UTC (а не в часовому поясі браузера).
export const formatUtcDay = (ts, locale) => new Date(utcDayStart(ts)).toLocaleDateString(locale, { timeZone: 'UTC' });
// «21.11» — коротка дата для осі графіка.
export const formatUtcDayShort = (ts, locale) => new Date(utcDayStart(ts)).toLocaleDateString(locale, {
    timeZone: 'UTC', day: '2-digit', month: '2-digit',
});
// «14:05» — час у UTC для осі графіка.
export const formatUtcTime = (ts, locale) => new Date(ts).toLocaleTimeString(locale, {
    timeZone: 'UTC', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
});
