// Підсумок набору угод — однаковий на головній і в історії трейдів
// (бекенд: domain/trade_day_stats.py). Сума ROE % свідомо не показується:
// вона дорівнює PnL лише за маржі 100 USDT.
export const EMPTY_TOTALS = { count: 0, wins: 0, pnl: 0, avg_roe: null };
const signed = (value, digits) => `${value > 0 ? '+' : ''}${value.toFixed(digits)}`;
// «+12.34 $» / «—» коли PnL невідомий.
export const formatPnl = (pnl) => (pnl === null ? '—' : `${signed(pnl, 2)} $`);
// «+1.23 %» / «—» коли угод немає.
export const formatRoe = (roe) => (roe === null ? '—' : `${signed(roe, 2)} %`);
// Частка прибуткових: «54.1 %» / «—».
export const formatWinRate = (wins, count) => (count === 0 ? '—' : `${((wins / count) * 100).toFixed(1)} %`);
